ValidationRule.errorConditionFormula:
AND( $Profile.Name <> "Administração", $Profile.Name <> "Gerente de renovações", $Profile.Name <> "Renovações", ISCHANGED(StageName), ISPICKVAL(PRIORVALUE(StageName), "PSL"), OR( Count_PSL_Fechada__c < 1, Count_PSL_Fechada__c > 1 ))
/* FUNCIONA: AND ( ISCHANGED(StageName), ISPICKVAL(PRIORVALUE(StageName), "PSL"), OR( Count_PSL_Fechada__c < 1, Count_PSL_Fechada__c > 1 ))
SINTAXE OK: AND ( ISCHANGED(StageName), ISPICKVAL(PRIORVALUE(StageName), "PSL"), Valida_PFP_existente__c < 1, OR( Count_PSL_Fechada__c < 1, Count_PSL_Fechada__c > 1, Count_PSL_Fechada__c = 0) ) */
